def log_stage(step_idx: int, code: str, stage_pct: int, msg: str, force: bool = False):
    global _LAST_STATUS_SYNC, _LAST_REPORTED_PCT
    stage_pct = max(0, min(100, int(stage_pct)))
    STAGE_PCTS[code] = stage_pct
    _, start_w, end_w = STAGE_WEIGHTS[step_idx - 1]
    overall_pct = int(start_w + (stage_pct / 100.0) * (end_w - start_w))
    now_str = datetime.now().strftime("%H:%M:%S")
    line = f"[{now_str}] TAHAP [{step_idx}/6] {code} ({stage_pct}% | Total: {overall_pct}%): {msg}"
    print(line, flush=True)

    now_ts = time.time()
    if force or abs(stage_pct - _LAST_REPORTED_PCT) >= 5 or (now_ts - _LAST_STATUS_SYNC) >= 15:
        _LAST_STATUS_SYNC = now_ts
        _LAST_REPORTED_PCT = stage_pct
        try:
            os.makedirs(BASE_STUDIO_DIR, exist_ok=True)
            lines = [
                f"STATUS: RUNNING ({overall_pct}%)",
                f"JOB: {JOB_TITLE}",
                f"CURRENT: [{step_idx}/6] {code} ({stage_pct}%)",
                f"MESSAGE: {msg}",
                "RINCIAN_TAHAP:",
            ]
            for idx, (s_code, _, _) in enumerate(STAGE_WEIGHTS, 1):
                lines.append(f"  [{idx}/6] {s_code}: {STAGE_PCTS[s_code]}%")
            with open(STATUS_FILE, "w", encoding="utf-8") as f:
                f.write("\n".join(lines) + "\n")
        except Exception:
            pass


def run_streamed(cmd, cwd=None, env=None, on_line=None, timeout=1800):
    proc = subprocess.Popen(
        cmd,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        bufsize=1,
        universal_newlines=True,
        errors="replace",
    )
    start_t = time.time()
    last_activity = start_t
    buf = ""
    tail_logs = []
    while True:
        ch = proc.stdout.read(1) if proc.stdout else ""
        if ch == "" and proc.poll() is not None:
            break
        if ch:
            last_activity = time.time()
            if ch in ("\r", "\n"):
                line = buf.strip()
                buf = ""
                if line:
                    tail_logs.append(line)
                    if len(tail_logs) > 40:
                        tail_logs.pop(0)
                    if on_line:
                        on_line(line)
            else:
                buf += ch
        if time.time() - start_t > timeout:
            proc.kill()
            raise RuntimeError(f"Timeout setelah {timeout} detik: {' '.join(cmd)}")
        if time.time() - last_activity > 240:
            proc.kill()
            raise RuntimeError(f"Proses macet tanpa output > 240 detik: {' '.join(cmd)}")
    rc = proc.wait()
    if rc != 0:
        raise RuntimeError(f"Command gagal (exit {rc}): {' '.join(cmd)}\n" + "\n".join(tail_logs[-15:]))


