    log_stage(1, "SETUP", 0, "Membersihkan direktori kerja sementara & memeriksa cache...", force=True)
    work_root = os.path.dirname(WORK_DIR)
    if os.path.exists(work_root):
        for entry in os.listdir(work_root):
            p = os.path.join(work_root, entry)
            if os.path.isdir(p) and entry != JOB_ID:
                shutil.rmtree(p, ignore_errors=True)
    os.makedirs(WORK_DIR, exist_ok=True)
    os.makedirs(os.path.join(WORK_DIR, "public", "sfx"), exist_ok=True)
    os.makedirs(PROJECTS_DIR, exist_ok=True)

    for sub in ("npm", "node_template", "py_site", "hf", "chromium"):
        os.makedirs(os.path.join(CACHE_DIR, sub), exist_ok=True)

    err_log = os.path.join(PROJECTS_DIR, "error_log.txt")
    if os.path.exists(err_log):
        try:
            os.remove(err_log)
        except Exception:
            pass

    py_site = os.path.join(CACHE_DIR, "py_site")
    if py_site not in sys.path:
        sys.path.insert(0, py_site)
    os.environ["PYTHONPATH"] = py_site + ":" + os.environ.get("PYTHONPATH", "")
    os.environ["NPM_CONFIG_CACHE"] = os.path.join(CACHE_DIR, "npm")
    os.environ["HF_HOME"] = os.path.join(CACHE_DIR, "hf")

    log_stage(1, "SETUP", 35, "Memeriksa paket Python (edge-tts)...", force=True)
    try:
        import edge_tts  # noqa: F401
    except ImportError:
        log_stage(1, "SETUP", 50, "Memasang edge-tts ke cache persisten...", force=True)
        subprocess.run(
            [sys.executable, "-m", "pip", "install", "-q", "--no-warn-script-location", "--target", py_site, "edge-tts"],
            check=True,
        )

    log_stage(1, "SETUP", 75, "Memeriksa FFmpeg & Node.js...", force=True)
    if not shutil.which("ffmpeg"):
        raise RuntimeError("FFmpeg tidak ditemukan di lingkungan runner.")
    node_ver = subprocess.check_output(["node", "-v"], text=True).strip()
    major = int(re.sub(r"^v", "", node_ver).split(".")[0])
    if major < 18:
        raise RuntimeError(f"Node.js >= 18 diperlukan, terdeteksi {node_ver}")

    log_stage(1, "SETUP", 100, f"Lingkungan siap (Node {node_ver}, FFmpeg & Edge-TTS aktif).", force=True)


