def write_silence_wav(path: str, duration_ms: int, sample_rate: int = 48000):
    n_samples = max(1, int(sample_rate * (duration_ms / 1000.0)))
    with wave.open(path, "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        wf.writeframes(b"\x00\x00" * n_samples)


def generate_bgm_wav(path: str, duration_sec: float, mood: str = "warm-pad", sample_rate: int = 48000):
    total_samples = max(sample_rate, int(duration_sec * sample_rate))
    chords = [
        [130.81, 164.81, 196.00, 246.94],
        [110.00, 130.81, 164.81, 196.00],
        [87.31, 130.81, 164.81, 174.61],
        [98.00, 123.47, 146.83, 164.81],
    ]
    bar_samples = sample_rate * 4
    frames = bytearray()
    for i in range(total_samples):
        t = i / sample_rate
        chord = chords[(i // bar_samples) % len(chords)]
        bar_pos = (i % bar_samples) / bar_samples
        env = math.sin(bar_pos * math.pi) * 0.55 + 0.45
        val = 0.0
        for idx, freq in enumerate(chord):
            val += math.sin(2.0 * math.pi * freq * t + idx * 0.4) * (0.24 / (1 + idx * 0.25))
        sample = int(max(-32767, min(32767, val * env * 14000)))
        frames.extend(struct.pack("<h", sample))
    with wave.open(path, "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        wf.writeframes(bytes(frames))


def generate_sfx_pack(sfx_dir: str, sample_rate: int = 48000):
    n_w = int(sample_rate * 0.40)
    buf_w = bytearray()
    seed = 12345
    lp = 0.0
    for i in range(n_w):
        p = i / n_w
        env = math.sin(p * math.pi) ** 1.6
        seed = (1103515245 * seed + 12345) & 0x7FFFFFFF
        noise = ((seed / 0x7FFFFFFF) * 2.0 - 1.0)
        lp = lp * 0.86 + noise * 0.14
        tone = math.sin(2 * math.pi * (140 + 240 * p) * (i / sample_rate)) * 0.25
        s = int(max(-32767, min(32767, (lp * 0.85 + tone) * env * 16000)))
        buf_w.extend(struct.pack("<h", s))
    with wave.open(os.path.join(sfx_dir, "whoosh.wav"), "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        wf.writeframes(bytes(buf_w))

    n_p = int(sample_rate * 0.18)
    buf_p = bytearray()
    for i in range(n_p):
        p = i / n_p
        env = math.exp(-p * 14.0)
        freq = 540.0 * math.exp(-p * 2.2) + 160.0
        s = int(max(-32767, min(32767, math.sin(2 * math.pi * freq * (i / sample_rate)) * env * 18000)))
        buf_p.extend(struct.pack("<h", s))
    with wave.open(os.path.join(sfx_dir, "pop.wav"), "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        wf.writeframes(bytes(buf_p))

    n_t = int(sample_rate * 0.12)
    buf_t = bytearray()
    for i in range(n_t):
        p = i / n_t
        env = math.exp(-p * 24.0)
        s = int(max(-32767, min(32767, math.sin(2 * math.pi * 1150.0 * (i / sample_rate)) * env * 15000)))
        buf_t.extend(struct.pack("<h", s))
    with wave.open(os.path.join(sfx_dir, "tick.wav"), "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        wf.writeframes(bytes(buf_t))

    n_c = int(sample_rate * 0.32)
    buf_c = bytearray()
    for i in range(n_c):
        p = i / n_c
        env = math.exp(-p * 7.5)
        t = i / sample_rate
        val = 0.6 * math.sin(2 * math.pi * 587.33 * t) + 0.4 * math.sin(2 * math.pi * 880.0 * t)
        s = int(max(-32767, min(32767, val * env * 16500)))
        buf_c.extend(struct.pack("<h", s))
    with wave.open(os.path.join(sfx_dir, "chime.wav"), "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        wf.writeframes(bytes(buf_c))

    n_th = int(sample_rate * 0.24)
    buf_th = bytearray()
    for i in range(n_th):
        p = i / n_th
        env = math.exp(-p * 11.0)
        freq = 95.0 - 52.0 * p
        s = int(max(-32767, min(32767, math.sin(2 * math.pi * freq * (i / sample_rate)) * env * 20000)))
        buf_th.extend(struct.pack("<h", s))
    with wave.open(os.path.join(sfx_dir, "thud.wav"), "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        wf.writeframes(bytes(buf_th))


def get_wav_duration_sec(wav_path: str) -> float:
    with wave.open(wav_path, "rb") as wf:
        return wf.getnframes() / float(wf.getframerate())


def detect_leading_trim_sec(raw_mp3: str, trimmed_wav: str) -> float:
    out = subprocess.check_output(
        [
            "ffprobe",
            "-v",
            "error",
            "-show_entries",
            "format=duration",
            "-of",
            "default=noprint_wrappers=1:nokey=1",
            raw_mp3,
        ],
        text=True,
    ).strip()
    raw_dur = float(out)
    trim_dur = get_wav_duration_sec(trimmed_wav)
    return max(0.0, (raw_dur - trim_dur) * 0.55)


async def synthesize_all_segments():
    import edge_tts

    audio_tmp = os.path.join(WORK_DIR, "audio_tmp")
    os.makedirs(audio_tmp, exist_ok=True)

    base_rate = int(VO_RATE.replace("%", "").replace("+", ""))
    base_pitch = int(VO_PITCH.replace("Hz", "").replace("+", ""))

    async def synth_one(idx: int, seg):
        scene_id, display_text, spoken_text, pause_ms, pitch_delta, rate_delta = seg
        r_val = base_rate + rate_delta
        p_val = base_pitch + pitch_delta
        rate_str = f"{r_val:+d}%"
        pitch_str = f"{p_val:+d}Hz"

        mp3_path = os.path.join(audio_tmp, f"seg_{idx:02d}.mp3")
        boundaries = []
        comm = edge_tts.Communicate(spoken_text, VO_VOICE, rate=rate_str, pitch=pitch_str)
        with open(mp3_path, "wb") as f:
            async for chunk in comm.stream():
                if chunk["type"] == "audio":
                    f.write(chunk["data"])
                elif chunk["type"] == "WordBoundary":
                    boundaries.append(
                        {
                            "word": chunk["text"],
                            "offset": chunk["offset"] / 10_000_000.0,
                            "duration": chunk["duration"] / 10_000_000.0,
                        }
                    )
        return idx, scene_id, display_text, pause_ms, mp3_path, boundaries

    tasks = [synth_one(i, seg) for i, seg in enumerate(SEGMENTS)]
    return await asyncio.gather(*tasks)


def step_2_audio():
    log_stage(2, "AUDIO", 0, "Menyintesis narasi VO Edge-TTS ejaan lisan Indonesia...", force=True)
    results = asyncio.run(synthesize_all_segments())
    log_stage(2, "AUDIO", 50, "Memangkas dead-air (45 ms) & menyisipkan jeda napas terkalibrasi...", force=True)

    audio_tmp = os.path.join(WORK_DIR, "audio_tmp")
    concat_list_path = os.path.join(audio_tmp, "concat.txt")
    concat_entries = []

    cursor_sec = 0.0
    scene_ranges = {}
    all_words = []

    for idx, scene_id, display_text, pause_ms, mp3_path, boundaries in results:
        wav_path = os.path.join(audio_tmp, f"seg_{idx:02d}.wav")
        subprocess.run(
            [
                "ffmpeg",
                "-y",
                "-i",
                mp3_path,
                "-af",
                "silenceremove=start_periods=1:start_duration=0.045:start_threshold=-54dB,areverse,silenceremove=start_periods=1:start_duration=0.045:start_threshold=-54dB,areverse",
                "-ar",
                "48000",
                "-ac",
                "1",
                "-c:a",
                "pcm_s16le",
                wav_path,
            ],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=True,
        )

        seg_dur = get_wav_duration_sec(wav_path)
        lead_trim = detect_leading_trim_sec(mp3_path, wav_path)
        seg_start = cursor_sec

        display_tokens = display_text.split()
        if boundaries and display_tokens:
            for w_idx, d_word in enumerate(display_tokens):
                b_idx = min(len(boundaries) - 1, int(round((w_idx / max(1, len(display_tokens))) * len(boundaries))))
                b = boundaries[b_idx]
                w_start = max(seg_start, seg_start + max(0.0, b["offset"] - lead_trim))
                w_end = max(w_start + 0.12, w_start + max(0.14, b["duration"]))
                s_frame = int(round(w_start * FPS))
                e_frame = max(s_frame + 2, int(round(w_end * FPS)))
                if all_words and s_frame < all_words[-1]["startFrame"]:
                    s_frame = all_words[-1]["startFrame"] + 1
                    e_frame = max(s_frame + 2, e_frame)
                all_words.append({"word": d_word, "startFrame": s_frame, "endFrame": e_frame})
        elif display_tokens:
            step_t = seg_dur / len(display_tokens)
            for w_idx, d_word in enumerate(display_tokens):
                s_frame = int(round((seg_start + w_idx * step_t) * FPS))
                e_frame = max(s_frame + 2, int(round((seg_start + (w_idx + 1) * step_t) * FPS)))
                all_words.append({"word": d_word, "startFrame": s_frame, "endFrame": e_frame})

        concat_entries.append(f"file '{wav_path}'")
        cursor_sec += seg_dur

        silence_path = os.path.join(audio_tmp, f"sil_{idx:02d}.wav")
        write_silence_wav(silence_path, pause_ms, 48000)
        concat_entries.append(f"file '{silence_path}'")
        cursor_sec += pause_ms / 1000.0

        if scene_id not in scene_ranges:
            scene_ranges[scene_id] = [seg_start, cursor_sec]
        else:
            scene_ranges[scene_id][1] = cursor_sec

    with open(concat_list_path, "w", encoding="utf-8") as f:
        f.write("\n".join(concat_entries) + "\n")

    raw_joined = os.path.join(audio_tmp, "raw_joined.wav")
    subprocess.run(
        ["ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", concat_list_path, "-c", "copy", raw_joined],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=True,
    )

    log_stage(2, "AUDIO", 75, "Mastering Studio Warmth (-16 LUFS / -1.5 dBTP)...", force=True)
    vo_out = os.path.join(WORK_DIR, "public", "vo.wav")
    subprocess.run(
        [
            "ffmpeg",
            "-y",
            "-i",
            raw_joined,
            "-af",
            "highpass=f=80,equalizer=f=220:t=q:w=1.2:g=2.0,equalizer=f=3200:t=q:w=1.5:g=2.5,equalizer=f=6800:t=q:w=2.0:g=-2.5,acompressor=threshold=-18dB:ratio=2.5:attack=15:release=120:makeup=2,loudnorm=I=-16:TP=-1.5:LRA=9,alimiter=limit=0.84:level=disabled",
            "-ar",
            "48000",
            "-ac",
            "1",
            "-c:a",
            "pcm_s16le",
            vo_out,
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=True,
    )

    total_audio_sec = get_wav_duration_sec(vo_out)
    total_frames = max(48, int(math.ceil(total_audio_sec * FPS)))

    ordered_scene_ids = ["scene_1", "scene_2", "scene_3", "scene_4", "scene_5"]
    scenes_manifest = []
    prev_end_frame = 0
    for idx, sid in enumerate(ordered_scene_ids):
        _, end_s = scene_ranges.get(sid, [prev_end_frame / FPS, total_audio_sec])
        end_f = total_frames if idx == len(ordered_scene_ids) - 1 else min(total_frames - 12, int(round(end_s * FPS)))
        dur_f = max(24, end_f - prev_end_frame)
        scenes_manifest.append({"id": sid, "startFrame": prev_end_frame, "durationInFrames": dur_f})
        prev_end_frame += dur_f

    log_stage(2, "AUDIO", 90, "Membangkitkan BGM ambient & SFX lokal 48 kHz...", force=True)
    generate_bgm_wav(os.path.join(WORK_DIR, "public", "bgm.wav"), total_frames / float(FPS), BGM_MOOD)
    generate_sfx_pack(os.path.join(WORK_DIR, "public", "sfx"))

    sfx_events = [{"type": "pop", "frame": 10, "volume": 0.14}]
    for idx, sc in enumerate(scenes_manifest):
        sf = sc["startFrame"]
        if idx > 0:
            sfx_events.append({"type": "whoosh", "frame": max(0, sf - 9), "volume": 0.12})
            sfx_events.append({"type": "pop", "frame": sf + 8, "volume": 0.14})
        if sc["id"] == "scene_2":
            sfx_events.append({"type": "tick", "frame": sf + 24, "volume": 0.11})
            sfx_events.append({"type": "chime", "frame": sf + 68, "volume": 0.14})
        elif sc["id"] == "scene_3":
            sfx_events.append({"type": "tick", "frame": sf + 26, "volume": 0.12})
        elif sc["id"] == "scene_4":
            sfx_events.append({"type": "chime", "frame": sf + 36, "volume": 0.14})
        elif sc["id"] == "scene_5":
            sfx_events.append({"type": "chime", "frame": sf + 16, "volume": 0.15})

    manifest = {
        "fps": FPS,
        "totalFrames": total_frames,
        "bgmMood": BGM_MOOD,
        "scenes": scenes_manifest,
        "words": all_words,
        "sfxEvents": sfx_events,
    }
    with open(os.path.join(WORK_DIR, "public", "manifest.json"), "w", encoding="utf-8") as f:
        json.dump(manifest, f, ensure_ascii=False, indent=2)

    log_stage(2, "AUDIO", 100, f"Audio & manifest selesai ({total_audio_sec:.1f} dtk | {total_frames} frame).", force=True)
    return total_frames


# ==============================================================================
# 5. TAHAP [3/6] PROJECT (DECODE + ZERO-REINSTALL .TAR CACHE)
# ==============================================================================
def step_3_project():
    log_stage(3, "PROJECT", 0, "Mendekode kode sumber proyek Remotion...", force=True)
    for rel_path, b64_data in PROJECT_FILES_B64.items():
        abs_path = os.path.join(WORK_DIR, rel_path)
        os.makedirs(os.path.dirname(abs_path), exist_ok=True)
        with open(abs_path, "wb") as f:
            f.write(base64.b64decode(b64_data))

    log_stage(3, "PROJECT", 25, "Memeriksa cache node_modules.tar...", force=True)
    pkg_path = os.path.join(WORK_DIR, "package.json")
    with open(pkg_path, "rb") as f:
        pkg_hash = hashlib.sha256(f.read()).hexdigest()

    node_tpl_dir = os.path.join(CACHE_DIR, "node_template")
    hash_file = os.path.join(node_tpl_dir, "pkg.hash")
    tar_file = os.path.join(node_tpl_dir, "node_modules.tar")
    legacy_nm = os.path.join(node_tpl_dir, "node_modules")

    cached_hash = open(hash_file).read().strip() if os.path.exists(hash_file) else ""

    if cached_hash == pkg_hash and os.path.exists(tar_file):
        log_stage(3, "PROJECT", 45, "Mengekstrak node_modules.tar ke SSD lokal...", force=True)
        subprocess.run(["tar", "-xf", tar_file, "-C", WORK_DIR], check=True)
        bin_dir = os.path.join(WORK_DIR, "node_modules", ".bin")
        if os.path.exists(bin_dir):
            subprocess.run(["chmod", "-R", "+x", bin_dir], check=False)
    elif cached_hash == pkg_hash and os.path.exists(legacy_nm):
        log_stage(3, "PROJECT", 45, "Migrasi cache folder node_modules ke arsip .tar tunggal...", force=True)
        shutil.copytree(legacy_nm, os.path.join(WORK_DIR, "node_modules"), symlinks=True)
        subprocess.run(["tar", "-cf", tar_file, "-C", WORK_DIR, "node_modules"], check=True)
    else:
        log_stage(3, "PROJECT", 40, "Menjalankan npm install (pertama kali) & menyimpan ke cache...", force=True)
        run_streamed(["npm", "install", "--no-audit", "--no-fund", "--prefer-offline"], cwd=WORK_DIR, timeout=900)
        subprocess.run(["tar", "-cf", tar_file, "-C", WORK_DIR, "node_modules"], check=True)
        with open(hash_file, "w") as f:
            f.write(pkg_hash)

    log_stage(3, "PROJECT", 75, "Menyiapkan cached Chromium Remotion...", force=True)
    chromium_tmp = "/tmp/remotion-chromium"
    os.makedirs(chromium_tmp, exist_ok=True)
    chromium_cache_dir = os.path.join(CACHE_DIR, "chromium")
    chromium_tar = os.path.join(chromium_cache_dir, "chromium.tar")

    env = os.environ.copy()
    env["PUPPETEER_CACHE_DIR"] = chromium_tmp
    env["PLAYWRIGHT_BROWSERS_PATH"] = chromium_tmp

    if os.path.exists(chromium_tar):
        subprocess.run(["tar", "-xf", chromium_tar, "-C", chromium_tmp], check=True)
        subprocess.run(["chmod", "-R", "+x", chromium_tmp], check=False)
    else:
        log_stage(3, "PROJECT", 85, "Mengunduh browser headless Remotion sekali ke cache...", force=True)
        run_streamed(["npx", "remotion", "browser", "ensure"], cwd=WORK_DIR, env=env, timeout=600)
        subprocess.run(["tar", "-cf", chromium_tar, "-C", chromium_tmp, "."], check=True)

    log_stage(3, "PROJECT", 100, "Proyek & browser siap dirender.", force=True)
    return env


# ==============================================================================
# 6. TAHAP [4/6] RENDER (MULTI-CORE CPU + ANTI-OOM + SMART FALLBACK)
# ==============================================================================
def step_4_render(total_frames: int, base_env: dict):
    log_stage(4, "RENDER", 0, f"Memulai bundling & render {total_frames} frame...", force=True)
    raw_out = os.path.join(WORK_DIR, "raw_out.mp4")

    cpu_cnt = os.cpu_count() or 2
    concurrency = max(2, min(4, cpu_cnt))

    env = base_env.copy()
    env["NODE_OPTIONS"] = "--max-old-space-size=3072"

    timeout_sec = max(1800, int(total_frames * 1.2) + 300)
    render_start = time.time()

    def parse_render_line(line: str):
        m = re.search(r"(\d+)\s*/\s*(\d+)", line)
        if m:
            cur = int(m.group(1))
            tot = max(1, int(m.group(2)))
            if tot >= total_frames // 2:
                pct = 5 + int((cur / tot) * 90)
                elapsed = max(0.1, time.time() - render_start)
                fps_rate = cur / elapsed
                eta = int((tot - cur) / max(0.05, fps_rate))
                log_stage(
                    4,
                    "RENDER",
                    min(95, pct),
                    f"Frame {cur}/{tot} ({fps_rate:.1f} fps | ETA ~{eta} dtk)",
                )
        elif "Bundling" in line or "Bundled" in line:
            log_stage(4, "RENDER", 4, line[:80])
        elif "Stitching" in line or "Encoding" in line:
            log_stage(4, "RENDER", 96, line[:80])

    primary_cmd = [
        "npx",
        "remotion",
        "render",
        "src/index.ts",
        "MainComp",
        raw_out,
        "--codec=h264",
        "--x264-preset=ultrafast",
        "--crf=18",
        f"--jpeg-quality={JPEG_QUALITY}",
        "--pixel-format=yuv420p",
        f"--concurrency={concurrency}",
        "--gl=swangle",
        "--log=verbose",
    ]

    try:
        run_streamed(primary_cmd, cwd=WORK_DIR, env=env, on_line=parse_render_line, timeout=timeout_sec)
    except Exception as primary_err:
        log_stage(4, "RENDER", 10, f"Beralih ke jalur cadangan concurrency=1 ({primary_err})...", force=True)
        if os.path.exists(raw_out):
            os.remove(raw_out)
        fallback_cmd = [
            "npx",
            "remotion",
            "render",
            "src/index.ts",
            "MainComp",
            raw_out,
            "--codec=h264",
            "--x264-preset=ultrafast",
            "--crf=19",
            "--jpeg-quality=70",
            "--pixel-format=yuv420p",
            "--concurrency=1",
            "--gl=angle",
            "--use-angle=swiftshader",
            "--log=verbose",
        ]
        run_streamed(fallback_cmd, cwd=WORK_DIR, env=env, on_line=parse_render_line, timeout=timeout_sec)

    log_stage(4, "RENDER", 100, "Render video mentah selesai.", force=True)
    return raw_out


# ==============================================================================
# 7. TAHAP [5/6] COMPRESS (H.264 SOCIAL MASTERING -14 LUFS)
# ==============================================================================
def step_5_compress(raw_out: str, total_frames: int):
    log_stage(5, "COMPRESS", 0, "Mengompresi MP4 final & mastering audio sosial (-14 LUFS)...", force=True)
    final_out = os.path.join(WORK_DIR, "final_out.mp4")
    total_us = max(1, int((total_frames / float(FPS)) * 1_000_000))

    def parse_ffmpeg(line: str):
        if line.startswith("out_time_us="):
            try:
                us = int(line.split("=", 1)[1])
                pct = min(99, int((us / total_us) * 100))
                log_stage(5, "COMPRESS", pct, f"Encoding H.264 + AAC ({pct}%)...")
            except ValueError:
                pass

    cmd = [
        "ffmpeg",
        "-y",
        "-i",
        raw_out,
        "-c:v",
        "libx264",
        "-preset",
        "veryfast",
        "-crf",
        "21",
        "-maxrate",
        "6M",
        "-bufsize",
        "12M",
        "-profile:v",
        "high",
        "-level",
        "4.1",
        "-pix_fmt",
        "yuv420p",
        "-af",
        "loudnorm=I=-14:TP=-1.5:LRA=11",
        "-c:a",
        "aac",
        "-b:a",
        "128k",
        "-ar",
        "48000",
        "-movflags",
        "+faststart",
        "-progress",
        "pipe:1",
        "-nostats",
        final_out,
    ]
    run_streamed(cmd, cwd=WORK_DIR, on_line=parse_ffmpeg, timeout=900)
    log_stage(5, "COMPRESS", 100, "Kompresi MP4 final selesai.", force=True)
    return final_out


# ==============================================================================
# 8. TAHAP [6/6] QC_PROMOTE (FFPROBE QUALITY GATE & AUTO-COVER PNG)
# ==============================================================================
def step_6_qc_promote(final_out: str):
    log_stage(6, "QC_PROMOTE", 0, "Menjalankan Quality Gate ffprobe...", force=True)
    if not os.path.exists(final_out) or os.path.getsize(final_out) < 100 * 1024:
        raise RuntimeError("File final_out.mp4 tidak valid atau ukuran < 100 KB.")

    probe_json = subprocess.check_output(
        [
            "ffprobe",
            "-v",
            "error",
            "-show_format",
            "-show_streams",
            "-of",
            "json",
            final_out,
        ],
        text=True,
    )
    meta = json.loads(probe_json)
    streams = meta.get("streams", [])
    v_streams = [s for s in streams if s.get("codec_type") == "video"]
    a_streams = [s for s in streams if s.get("codec_type") == "audio"]
    if not v_streams or not a_streams:
        raise RuntimeError("Stream video atau audio hilang pada hasil akhir.")

    v_dur = float(v_streams[0].get("duration") or meta["format"].get("duration", 0))
    a_dur = float(a_streams[0].get("duration") or v_dur)
    if abs(v_dur - a_dur) > 0.35:
        raise RuntimeError(f"Selisih durasi audio-video terlalu besar: {abs(v_dur - a_dur):.2f} detik")

    bitrate_mbps = int(meta["format"].get("bit_rate", 0)) / 1_000_000.0
    size_mb = os.path.getsize(final_out) / (1024 * 1024)
    log_stage(6, "QC_PROMOTE", 45, f"Lolos QC ({v_dur:.1f} dtk | {size_mb:.2f} MB | {bitrate_mbps:.2f} Mbps).", force=True)

    cover_tmp = os.path.join(WORK_DIR, "cover_out.png")
    ss = min(1.2, max(0.3, v_dur * 0.08))
    subprocess.run(
        ["ffmpeg", "-y", "-ss", f"{ss:.2f}", "-i", final_out, "-vframes", "1", "-q:v", "2", cover_tmp],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=True,
    )
    log_stage(6, "QC_PROMOTE", 75, "Sampul cover.png berhasil diekstrak.", force=True)

    dest_mp4 = os.path.join(PROJECTS_DIR, f"{JOB_TITLE}_final.mp4")
    dest_cover = os.path.join(PROJECTS_DIR, f"{JOB_TITLE}_cover.png")
    dest_report = os.path.join(PROJECTS_DIR, f"{JOB_TITLE}_render_report.json")

    shutil.copy2(final_out, dest_mp4)
    shutil.copy2(cover_tmp, dest_cover)

    report = {
        "jobTitle": JOB_TITLE,
        "status": "COMPLETED",
        "durationSec": round(v_dur, 2),
        "sizeMB": round(size_mb, 2),
        "bitrateMbps": round(bitrate_mbps, 2),
        "resolution": f"{WIDTH}x{HEIGHT}",
        "fps": FPS,
        "mp4Path": dest_mp4,
        "coverPath": dest_cover,
        "completedAt": datetime.now().isoformat(),
    }
    with open(dest_report, "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2)

    log_stage(6, "QC_PROMOTE", 100, f"Selesai! Output: {dest_mp4} & {dest_cover}", force=True)
    with open(STATUS_FILE, "w", encoding="utf-8") as f:
        f.write(
            f"STATUS: COMPLETED (100%)\n"
            f"DURATION: {v_dur:.2f}s | SIZE: {size_mb:.2f} MB | BITRATE: {bitrate_mbps:.2f} Mbps\n"
            f"MP4: {dest_mp4}\n"
            f"COVER: {dest_cover}\n"
        )


def main():
    try:
        step_1_setup()
        total_frames = step_2_audio()
        env = step_3_project()
        raw_out = step_4_render(total_frames, env)
        final_out = step_5_compress(raw_out, total_frames)
        step_6_qc_promote(final_out)
    except Exception as exc:
        err_msg = f"STATUS: FAILED\nERROR: {exc}\n"
        print(err_msg, file=sys.stderr, flush=True)
        try:
            os.makedirs(PROJECTS_DIR, exist_ok=True)
            with open(os.path.join(PROJECTS_DIR, "error_log.txt"), "w", encoding="utf-8") as f:
                f.write(err_msg)
            with open(STATUS_FILE, "w", encoding="utf-8") as f:
                f.write(err_msg)
        except Exception:
            pass
        sys.exit(1)
    finally:
        if os.path.exists(WORK_DIR):
            shutil.rmtree(WORK_DIR, ignore_errors=True)


if __name__ == "__main__":
    main()
